import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/components/ui/use-toast';
import {
  ArrowLeft, Save, Loader2, Upload, X,
  LayoutDashboard, TrendingUp, Sparkles, Tag,
  ImageIcon, Maximize2, Layers, Search, PackageMinus, GripVertical
} from 'lucide-react';

/* ─── Type config ──────────────────────────────── */
const TYPE_CONFIG: Record<string, { label: string; icon: React.ReactNode; color: string; bg: string }> = {
  featured_categories: { label: 'Featured Categories', icon: <Layers className="h-4 w-4" />,          color: 'text-blue-700',   bg: 'bg-blue-100'   },
  trending:            { label: 'Trending',             icon: <TrendingUp className="h-4 w-4" />,      color: 'text-rose-700',   bg: 'bg-rose-100'   },
  new_arrivals:        { label: 'New Arrivals',         icon: <Sparkles className="h-4 w-4" />,        color: 'text-amber-700',  bg: 'bg-amber-100'  },
  promo:               { label: 'Promo Banner',         icon: <Tag className="h-4 w-4" />,             color: 'text-green-700',  bg: 'bg-green-100'  },
  category:            { label: 'Category Section',    icon: <Layers className="h-4 w-4" />,          color: 'text-cyan-700',   bg: 'bg-cyan-100'   },
  big_size:            { label: 'Big Size',             icon: <Maximize2 className="h-4 w-4" />,       color: 'text-orange-700', bg: 'bg-orange-100' },
  banner:              { label: 'Full Banner',          icon: <ImageIcon className="h-4 w-4" />,       color: 'text-pink-700',   bg: 'bg-pink-100'   },
  semi_banner:         { label: 'Semi Banner',          icon: <ImageIcon className="h-4 w-4" />,       color: 'text-indigo-700', bg: 'bg-indigo-100' },
};

/* ─── Section card wrapper ─────────────────────── */
function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="rounded-2xl border border-border bg-card overflow-hidden">
      <div className="px-6 py-4 border-b border-border bg-muted/30">
        <h3 className="font-semibold text-sm text-foreground">{title}</h3>
      </div>
      <div className="p-6 space-y-5">{children}</div>
    </div>
  );
}

/* ─── Field wrapper ────────────────────────────── */
function Field({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) {
  return (
    <div className="space-y-1.5">
      <Label className="font-medium">{label}</Label>
      {hint && <p className="text-xs text-muted-foreground">{hint}</p>}
      {children}
    </div>
  );
}

/* ─── Image uploader ───────────────────────────── */
function ImageUpload({
  label, value, uploading, onChange, onClear,
}: { label: string; value: string; uploading: boolean; onChange: (e: React.ChangeEvent<HTMLInputElement>) => void; onClear: () => void }) {
  return (
    <Field label={label}>
      <div className="relative rounded-xl border-2 border-dashed border-border hover:border-primary/50 transition-colors overflow-hidden">
        <label className="flex flex-col items-center justify-center gap-3 cursor-pointer min-h-[140px] p-4">
          <input type="file" accept="image/*" className="hidden" onChange={onChange} disabled={uploading} />
          {uploading ? (
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          ) : value ? (
            <div className="relative w-full">
              <img src={value} alt="Uploaded" className="max-h-36 mx-auto rounded-lg object-contain" />
            </div>
          ) : (
            <>
              <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center">
                <Upload className="h-5 w-5 text-primary" />
              </div>
              <div className="text-center">
                <p className="text-sm font-medium">Click to upload</p>
                <p className="text-xs text-muted-foreground">PNG, JPG, WebP</p>
              </div>
            </>
          )}
        </label>
        {value && !uploading && (
          <button
            type="button"
            onClick={onClear}
            className="absolute top-2 right-2 w-7 h-7 bg-black/60 text-white rounded-full flex items-center justify-center hover:bg-black/80 transition-colors"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        )}
      </div>
    </Field>
  );
}

/* ─── Main page ────────────────────────────────── */
export default function EditHomepageSectionPage() {
  const router = useRouter();
  const params = useParams();
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploading1, setUploading1] = useState(false);
  const [uploading2, setUploading2] = useState(false);
  const [productSearch, setProductSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [searching, setSearching] = useState(false);
  const [searchResults, setSearchResults] = useState<{ _id: string; name: string; images?: string[] }[]>([]);

  const [categories, setCategories] = useState<{ _id: string; name: string }[]>([]);
  const [initialProducts, setInitialProducts] = useState<{ _id: string; name: string; images?: string[] }[]>([]);
  // Store only the full product objects for the currently Linked ones
  const [linkedProductsData, setLinkedProductsData] = useState<Record<string, { _id: string; name: string; images?: string[] }>>({});

  const [form, setForm] = useState({
    type: 'trending',
    image: '',
    title: '',
    subtitle: '',
    buttonText: '',
    link: '',
    image2: '',
    link2: '',
    active: true,
    order: 0,
    categoryId: '',
    linkedProductIds: [] as string[],
  });

  // Load categories and initial products
  useEffect(() => {
    Promise.all([
      fetch('/api/categories').then(r => r.json()),
      fetch('/api/products?limit=200').then(r => r.json()),
    ]).then(([cats, prods]) => {
      setCategories(Array.isArray(cats) ? cats : []);
      setInitialProducts(Array.isArray(prods?.data) ? prods.data : []);
    });
  }, []);

  useEffect(() => {
    const id = params.id as string;
    if (!id) return;
    fetch('/api/homepage-sections')
      .then(r => r.json())
      .then(data => {
        const s = data.find((x: any) => x._id === id);
        if (s) {
          const linkedIds = (s.linkedProductIds || []).map((p: any) => typeof p === 'object' ? p._id : p);
          setForm({
            type: s.type,
            title: s.title || '',
            image: s.image || '',
            link: s.link || '',
            image2: s.image2 || '',
            link2: s.link2 || '',
            linkedProductIds: linkedIds,
            categoryId: s.categoryId?._id || s.categoryId || '',
            order: s.order ?? 0,
            active: s.active ?? true,
            subtitle: s.subtitle || '',
            buttonText: s.buttonText || '',
          });

          // Fetch data for the linked products
          if (linkedIds.length > 0) {
             const idsParams = linkedIds.map((id:string) => `ids=${id}`).join('&');
             fetch(`/api/products/batch?${idsParams}`)
               .then(r => r.ok ? r.json() : [])
               .then(data => {
                  const map: Record<string, any> = {};
                  data.forEach((p:any) => map[p._id] = p);
                  setLinkedProductsData(map);
               }).catch(()=>{});
          }
        }
      })
      .catch(() => toast({ title: 'Failed to load section', variant: 'destructive' }))
      .finally(() => setLoading(false));
  }, [params.id]);

  // Debounce search
  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(productSearch);
    }, 400);
    return () => clearTimeout(handler);
  }, [productSearch]);

  // Fire search API
  useEffect(() => {
    if (!debouncedSearch) {
      setSearchResults([]);
      return;
    }
    setSearching(true);
    fetch(`/api/products?search=${encodeURIComponent(debouncedSearch)}&limit=20`)
      .then(r => r.json())
      .then(data => setSearchResults(Array.isArray(data?.data) ? data.data : []))
      .catch(() => setSearchResults([]))
      .finally(() => setSearching(false));
  }, [debouncedSearch]);

  const set = (key: string, value: any) => setForm(f => ({ ...f, [key]: value }));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      const res = await fetch(`/api/homepage-sections/${params.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, categoryId: form.categoryId || null }),
      });
      if (res.ok) {
        toast({ title: 'Section saved successfully' });
        router.push('/admin/homepage');
      } else {
        const err = await res.json();
        toast({ title: err.error || 'Failed to save', variant: 'destructive' });
      }
    } catch {
      toast({ title: 'Error saving section', variant: 'destructive' });
    } finally {
      setSaving(false);
    }
  };

  const toggleProduct = (p: { _id: string; name: string; images?: string[] }) => {
    const isAdding = !form.linkedProductIds.includes(p._id);
    if (isAdding) {
      set('linkedProductIds', [...form.linkedProductIds, p._id]);
      setLinkedProductsData(prev => ({ ...prev, [p._id]: p }));
    } else {
      set('linkedProductIds', form.linkedProductIds.filter(x => x !== p._id));
    }
  };

  const handleUpload = async (
    e: React.ChangeEvent<HTMLInputElement>,
    field: 'image' | 'image2',
    setUpl: (v: boolean) => void,
  ) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUpl(true);
    try {
      const fd = new FormData();
      fd.append('file', file);
      const res = await fetch('/api/upload', { method: 'POST', body: fd });
      const data = await res.json();
      if (data.url) set(field, data.url);
      else toast({ title: 'Upload failed', variant: 'destructive' });
    } catch {
      toast({ title: 'Upload error', variant: 'destructive' });
    } finally { setUpl(false); }
  };

  const cfg = TYPE_CONFIG[form.type] || { label: form.type, icon: <Layers className="h-4 w-4" />, color: 'text-primary', bg: 'bg-primary/10' };
  const hasBanner = form.type === 'banner' || form.type === 'semi_banner';
  const hasProducts = ['trending', 'new_arrivals', 'category', 'promo'].includes(form.type);

  // Derive the combined list to render
  let listToRender = initialProducts;
  if (productSearch) {
    const searchLower = productSearch.toLowerCase();
    const localMatches = initialProducts.filter(p => p.name.toLowerCase().includes(searchLower));

    // Combine local instant matches with delayed API results, deduplicated by ID
    const merged = new Map();
    localMatches.forEach(p => merged.set(p._id, p));
    searchResults.forEach(p => merged.set(p._id, p));
    listToRender = Array.from(merged.values());
  }

  const unselectedToRender = listToRender.filter(p => !form.linkedProductIds.includes(p._id));

  // Selected products at the top
  const selectedToRender = form.linkedProductIds.map(id => linkedProductsData[id] || initialProducts.find(x => x._id === id) || { _id: id, name: 'Loading...' });

  if (loading) return (
    <div className="flex items-center justify-center py-24">
      <Loader2 className="h-8 w-8 animate-spin text-primary" />
    </div>
  );

  return (
    <div className="max-w-4xl space-y-6 pb-20">
      {/* ── Breadcrumb / header ── */}
      <div>
        <Link
          href="/admin/homepage"
          className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors mb-4"
        >
          <ArrowLeft className="h-4 w-4" /> Back to Homepage
        </Link>

        <div className="flex items-start justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${cfg.bg} ${cfg.color}`}>
              {cfg.icon}
            </div>
            <div>
              <h2 className="text-xl font-bold">Edit Section</h2>
              <p className="text-sm text-muted-foreground">{form.title || '(No title)'} · {cfg.label}</p>
            </div>
          </div>

          {/* Active toggle */}
          <button
            type="button"
            onClick={() => set('active', !form.active)}
            className={`flex items-center gap-1.5 text-sm font-medium px-4 py-2 rounded-xl border transition-colors shrink-0 ${
              form.active
                ? 'bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100'
                : 'bg-muted text-muted-foreground border-border hover:bg-muted/80'
            }`}
          >
            <span className={`w-2 h-2 rounded-full ${form.active ? 'bg-emerald-500' : 'bg-muted-foreground'}`} />
            {form.active ? 'Live' : 'Hidden'}
          </button>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-5">
        {/* ── Section Config ── */}
        <Section title="Section Configuration">
          <Field label="Section Type">
            <Select value={form.type} onValueChange={v => set('type', v)}>
              <SelectTrigger className="h-10">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="featured_categories">Featured Categories</SelectItem>
                <SelectItem value="trending">Trending</SelectItem>
                <SelectItem value="new_arrivals">New Arrivals</SelectItem>
                <SelectItem value="promo">Promo Banner</SelectItem>
                <SelectItem value="category">Category Section</SelectItem>
                <SelectItem value="big_size">Big Size (XL / XXL etc.)</SelectItem>
                <SelectItem value="banner">Full Banner</SelectItem>
                <SelectItem value="semi_banner">Semi Banner (2 images)</SelectItem>
              </SelectContent>
            </Select>
          </Field>

          <Field label="Section Title" hint={form.type === 'big_size' ? 'Products with XL, XXL, 2XL, 3XL sizes are shown automatically.' : undefined}>
            <Input
              value={form.title}
              onChange={e => set('title', e.target.value)}
              placeholder="e.g. Trending Collections"
            />
          </Field>

          {/* Order + Active row */}
          <div className="flex items-end gap-4">
            <Field label="Display Order">
              <Input
                type="number"
                value={form.order}
                onChange={e => set('order', parseInt(e.target.value, 10) || 0)}
                className="w-28"
              />
            </Field>
          </div>
        </Section>

        {/* ── Banner images ── */}
        {hasBanner && (
          <Section title={form.type === 'semi_banner' ? 'Banner Images' : 'Banner Image'}>
            <ImageUpload
              label={form.type === 'semi_banner' ? 'Left Image *' : 'Image *'}
              value={form.image}
              uploading={uploading1}
              onChange={e => handleUpload(e, 'image', setUploading1)}
              onClear={() => set('image', '')}
            />
            <Field label="Link (optional URL)">
              <Input
                value={form.link}
                onChange={e => set('link', e.target.value)}
                placeholder="/products?category=..."
              />
            </Field>

            {form.type === 'semi_banner' && (
              <>
                <div className="border-t border-border pt-5" />
                <ImageUpload
                  label="Right Image *"
                  value={form.image2}
                  uploading={uploading2}
                  onChange={e => handleUpload(e, 'image2', setUploading2)}
                  onClear={() => set('image2', '')}
                />
                <Field label="Right Link (optional URL)">
                  <Input
                    value={form.link2}
                    onChange={e => set('link2', e.target.value)}
                    placeholder="/products?category=..."
                  />
                </Field>
              </>
            )}
          </Section>
        )}

        {/* ── Category picker ── */}
        {form.type === 'category' && (
          <Section title="Category">
            <Field label="Linked Category">
              <Select value={form.categoryId} onValueChange={v => set('categoryId', v)}>
                <SelectTrigger className="h-10">
                  <SelectValue placeholder="Select a category" />
                </SelectTrigger>
                <SelectContent>
                  {categories.map(c => (
                    <SelectItem key={c._id} value={c._id}>{c.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </Field>
          </Section>
        )}

        {/* ── Linked Products ── */}
        {hasProducts && (
          <Section title={`Linked Products (${form.linkedProductIds.length} selected)`}>
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search products by name..."
                className="pl-9 h-10"
                value={productSearch}
                onChange={e => setProductSearch(e.target.value)}
              />
              {searching && <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 animate-spin text-muted-foreground" />}
            </div>

            {/* Clear selected button */}
            {form.linkedProductIds.length > 0 && (
              <div className="flex justify-end">
                <button
                  type="button"
                  onClick={() => set('linkedProductIds', [])}
                  className="text-xs font-medium text-destructive hover:underline"
                >
                  Clear all selected ({form.linkedProductIds.length})
                </button>
              </div>
            )}

            {/* Unified Product list */}
            <div className="rounded-xl border border-border max-h-[450px] overflow-y-auto overflow-x-hidden bg-muted/10">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 p-2">

                {/* 1. Show Selected Products first (Pinned to top) */}
                {selectedToRender.map(p => {
                  const img = p.images?.[0];
                  return (
                    <label
                      key={p._id}
                      className="group flex items-center gap-3 p-2 rounded-lg border cursor-pointer transition-all bg-primary/5 border-primary/40 shadow-sm"
                    >
                      <div className="w-4 h-4 rounded border flex items-center justify-center shrink-0 transition-colors bg-primary border-primary text-primary-foreground">
                        <svg viewBox="0 0 10 8" className="w-2.5 h-2.5 fill-current"><path d="M1 4l3 3 5-6" stroke="currentColor" strokeWidth="1.5" fill="none" strokeLinecap="round" strokeLinejoin="round" /></svg>
                      </div>
                      <input type="checkbox" className="hidden" checked={true} onChange={() => toggleProduct(p)} />

                      <div className="relative w-10 h-10 rounded-md bg-muted border border-border shrink-0 overflow-hidden flex items-center justify-center bg-card">
                        {img ? <img src={img} alt={p.name} className="w-full h-full object-cover" /> : <ImageIcon className="w-4 h-4 text-muted-foreground/50" />}
                      </div>
                      <span className="text-sm truncate w-full font-semibold text-foreground">
                        {p.name}
                      </span>
                    </label>
                  );
                })}

                {/* 2. Show Unselected Products */}
                {(!productSearch || !searching) && unselectedToRender.length === 0 && selectedToRender.length === 0 ? (
                  <div className="col-span-1 sm:col-span-2 py-8 text-center text-sm text-muted-foreground">
                    {productSearch ? 'No matches found.' : 'No products available.'}
                  </div>
                ) : (
                  unselectedToRender.map(p => {
                    const img = p.images?.[0];
                    return (
                      <label
                        key={p._id}
                        className="group flex items-center gap-3 p-2 rounded-lg border cursor-pointer transition-all bg-card border-border hover:border-border/80 hover:bg-muted/30"
                      >
                        <div className="w-4 h-4 rounded border flex items-center justify-center shrink-0 transition-colors border-input bg-background group-hover:border-primary/50" />
                        <input type="checkbox" className="hidden" checked={false} onChange={() => toggleProduct(p)} />

                        <div className="relative w-10 h-10 rounded-md bg-muted border border-border shrink-0 overflow-hidden flex items-center justify-center">
                          {img ? <img src={img} alt={p.name} className="w-full h-full object-cover" /> : <ImageIcon className="w-4 h-4 text-muted-foreground/50" />}
                        </div>
                        <span className="text-sm truncate w-full text-foreground/80 group-hover:text-foreground">
                          {p.name}
                        </span>
                      </label>
                    );
                  })
                )}
              </div>
            </div>
          </Section>
        )}

        {/* ── Save / Cancel ── */}
        <div className="flex gap-3 pt-2">
          <Button type="submit" disabled={saving} className="min-w-[120px]">
            {saving
              ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" /> Saving…</>
              : <><Save className="mr-2 h-4 w-4" /> Save Changes</>}
          </Button>
          <Button type="button" variant="outline" asChild>
            <Link href="/admin/homepage">Cancel</Link>
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from '@/components/ui/use-toast';
import { Loader2 } from 'lucide-react';

export default function NewHomepageSectionPage() {
  const router = useRouter();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [categories, setCategories] = useState<{ _id: string; name: string }[]>([]);
  const [products, setProducts] = useState<{ _id: string; name: string }[]>([]);
  const [form, setForm] = useState({
    type: 'trending',
    title: '',
    linkedProductIds: [] as string[],
    categoryId: '',
    image: '',
    link: '',
    image2: '',
    link2: '',
    order: 0,
    active: true,
  });

  useEffect(() => {
    Promise.all([fetch('/api/categories').then((r) => r.json()), fetch('/api/products?limit=100').then((r) => r.json())]).then(
      ([cats, prods]) => {
        setCategories(Array.isArray(cats) ? cats : []);
        setProducts(Array.isArray(prods?.data) ? prods.data : []);
      }
    );
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await fetch('/api/homepage-sections', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...form,
          categoryId: form.categoryId || undefined,
        }),
      });
      if (res.ok) {
        toast({ title: 'Section created' });
        router.push('/admin/homepage');
      } else {
        const err = await res.json();
        toast({ title: err.error || 'Failed', variant: 'destructive' });
      }
    } catch {
      toast({ title: 'Error', variant: 'destructive' });
    } finally {
      setLoading(false);
    }
  };

  const toggleProduct = (id: string) => {
    setForm((f) => ({
      ...f,
      linkedProductIds: f.linkedProductIds.includes(id)
        ? f.linkedProductIds.filter((x) => x !== id)
        : [...f.linkedProductIds, id],
    }));
  };

  const [uploading1, setUploading1] = useState(false);
  const [uploading2, setUploading2] = useState(false);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>, fieldName: 'image' | 'image2', setUploading: (v: boolean) => void) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      setUploading(true);
      const fd = new FormData();
      fd.append('file', file);
      const res = await fetch('/api/upload', { method: 'POST', body: fd });
      const data = await res.json();
      if (data.url) {
        setForm((f) => ({ ...f, [fieldName]: data.url }));
      } else {
        toast({ title: 'Upload failed', variant: 'destructive' });
      }
    } catch (err) {
      toast({ title: 'Upload error', variant: 'destructive' });
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="max-w-2xl space-y-6">
      <h2 className="text-3xl font-bold">Add Homepage Section</h2>
      <form onSubmit={handleSubmit}>
        <Card>
          <CardHeader>
            <CardTitle>Section config</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label>Type</Label>
              <Select value={form.type} onValueChange={(v) => setForm((f) => ({ ...f, type: v }))}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="featured_categories">Featured Categories</SelectItem>
                  <SelectItem value="trending">Trending</SelectItem>
                  <SelectItem value="new_arrivals">New Arrivals</SelectItem>
                  <SelectItem value="promo">Promo</SelectItem>
                  <SelectItem value="category">Category Section</SelectItem>
                  <SelectItem value="big_size">Big Size (XL/XXL etc.)</SelectItem>
                  <SelectItem value="banner">Full Banner</SelectItem>
                  <SelectItem value="semi_banner">Semi Banner</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Title (section heading)</Label>
              <Input
                value={form.title}
                onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}
                placeholder={form.type === 'big_size' ? 'e.g. Big Size' : 'e.g. Trending Now'}
              />
              {form.type === 'big_size' && (
                <p className="text-sm text-muted-foreground mt-1">
                  Products with sizes XL, XXL, 2XL, 3XL, 4XL are shown automatically.
                </p>
              )}
            </div>
            {(form.type === 'trending' || form.type === 'new_arrivals' || form.type === 'category') && (
              <div>
                <Label>Linked products (show these in this section)</Label>
                <div className="border rounded-lg p-3 max-h-48 overflow-y-auto space-y-2 mt-2">
                  {products.slice(0, 50).map((p) => (
                    <label key={p._id} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={form.linkedProductIds.includes(p._id)}
                        onChange={() => toggleProduct(p._id)}
                      />
                      <span className="text-sm">{p.name}</span>
                    </label>
                  ))}
                </div>
              </div>
            )}
            {form.type === 'category' && (
              <div>
                <Label>Category (optional)</Label>
                <Select
                  value={form.categoryId}
                  onValueChange={(v) => setForm((f) => ({ ...f, categoryId: v }))}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select category" />
                  </SelectTrigger>
                  <SelectContent>
                    {categories.map((c) => (
                      <SelectItem key={c._id} value={c._id}>
                        {c.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            {(form.type === 'banner' || form.type === 'semi_banner') && (
              <>
                <div>
                  <Label>{form.type === 'semi_banner' ? 'Left Image *' : 'Image *'}</Label>
                  <div className="mt-2 border-2 border-dashed rounded-lg p-6 text-center">
                    <label className="cursor-pointer">
                      <input
                        type="file"
                        accept="image/*"
                        className="hidden"
                        onChange={(e) => handleFileSelect(e, 'image', setUploading1)}
                        disabled={uploading1}
                      />
                      {uploading1 ? (
                        <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                      ) : form.image ? (
                        <img src={form.image} alt="Banner" className="max-h-40 mx-auto rounded" />
                      ) : (
                        <span className="text-sm text-muted-foreground">Click to upload image</span>
                      )}
                    </label>
                  </div>
                </div>
                <div>
                  <Label>Link (Optional URL)</Label>
                  <Input
                    value={form.link}
                    onChange={(e) => setForm((f) => ({ ...f, link: e.target.value }))}
                    placeholder="/products?category=..."
                  />
                </div>
              </>
            )}

            {form.type === 'semi_banner' && (
              <>
                <div className="pt-4 border-t">
                  <Label>Right Image *</Label>
                  <div className="mt-2 border-2 border-dashed rounded-lg p-6 text-center">
                    <label className="cursor-pointer">
                      <input
                        type="file"
                        accept="image/*"
                        className="hidden"
                        onChange={(e) => handleFileSelect(e, 'image2', setUploading2)}
                        disabled={uploading2}
                      />
                      {uploading2 ? (
                        <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                      ) : form.image2 ? (
                        <img src={form.image2} alt="Semi Banner Right" className="max-h-40 mx-auto rounded" />
                      ) : (
                        <span className="text-sm text-muted-foreground">Click to upload 2nd image</span>
                      )}
                    </label>
                  </div>
                </div>
                <div>
                  <Label>Right Link (Optional URL)</Label>
                  <Input
                    value={form.link2}
                    onChange={(e) => setForm((f) => ({ ...f, link2: e.target.value }))}
                    placeholder="/products?category=..."
                  />
                </div>
              </>
            )}

            <div className="flex items-center gap-4">
              <div className="flex items-center space-x-2">
                <Checkbox
                  id="active"
                  checked={form.active}
                  onCheckedChange={(c) => setForm((f) => ({ ...f, active: !!c }))}
                />
                <Label htmlFor="active">Active</Label>
              </div>
              <div>
                <Label>Order</Label>
                <Input
                  type="number"
                  value={form.order}
                  onChange={(e) => setForm((f) => ({ ...f, order: parseInt(e.target.value, 10) || 0 }))}
                  className="w-24"
                />
              </div>
            </div>
          </CardContent>
        </Card>
        <div className="flex gap-4 mt-6">
          <Button type="submit" disabled={loading}>
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Create Section
          </Button>
          <Button type="button" variant="outline" asChild>
            <Link href="/admin/homepage">Cancel</Link>
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { useToast } from '@/components/ui/use-toast';
import { Loader2, ArrowLeft } from 'lucide-react';
import { format } from 'date-fns';

interface HistoryItem {
    _id: string;
    productId: string;
    productName: string;
    variant: {
        size: string;
        color: string;
    };
    changeAmount: number;
    reason: string;
    referenceId?: string;
    createdAt: string;
}

export default function AdminInventoryHistoryPage() {
    const { data: session, status } = useSession();
    const router = useRouter();
    const { toast } = useToast();

    const [history, setHistory] = useState<HistoryItem[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (status === 'unauthenticated' || (session?.user as any)?.role !== 'admin') {
            router.push('/admin/signin');
            return;
        }

        if (status === 'authenticated') {
            fetchHistory();
        }
    }, [status, session, router]);

    const fetchHistory = async () => {
        setLoading(true);
        try {
            const response = await fetch('/api/admin/inventory/history?limit=100');
            if (response.ok) {
                const data = await response.json();
                setHistory(data);
            } else {
                toast({ title: 'Failed to fetch history', variant: 'destructive' });
            }
        } catch (error) {
            console.error('Error:', error);
            toast({ title: 'Error fetching history', variant: 'destructive' });
        } finally {
            setLoading(false);
        }
    };

    if (status === 'loading') {
        return <div className="flex h-[50vh] items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-muted-foreground" /></div>;
    }

    return (
        <div className="space-y-6">
            <div className="flex items-center gap-4">
                <Button variant="ghost" size="icon" onClick={() => router.push('/admin/inventory')}>
                    <ArrowLeft className="h-4 w-4" />
                </Button>
                <div>
                    <h2 className="text-2xl font-bold tracking-tight">Inventory History</h2>
                    <p className="text-muted-foreground">Recent stock adjustments and order deductions.</p>
                </div>
            </div>

            <div className="rounded-md border bg-card">
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead>Date & Time</TableHead>
                            <TableHead>Product</TableHead>
                            <TableHead>Variant (Size, Color)</TableHead>
                            <TableHead className="text-right">Change</TableHead>
                            <TableHead>Reason</TableHead>
                            <TableHead>Reference ID</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {loading ? (
                            <TableRow>
                                <TableCell colSpan={6} className="h-32 text-center">
                                    <Loader2 className="h-6 w-6 animate-spin mx-auto text-muted-foreground" />
                                </TableCell>
                            </TableRow>
                        ) : history.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={6} className="h-32 text-center text-muted-foreground">
                                    No history records found.
                                </TableCell>
                            </TableRow>
                        ) : (
                            history.map((record) => (
                                <TableRow key={record._id}>
                                    <TableCell className="whitespace-nowrap text-sm text-muted-foreground">
                                        {format(new Date(record.createdAt), 'MMM d, yyyy h:mm a')}
                                    </TableCell>
                                    <TableCell className="font-medium">
                                        {record.productName}
                                    </TableCell>
                                    <TableCell>
                                        {record.variant ? (
                                            <div className="flex gap-1.5">
                                                <Badge variant="outline" className="text-xs font-normal">{record.variant.size || 'N/A'}</Badge>
                                                <Badge variant="outline" className="text-xs font-normal">{record.variant.color || 'N/A'}</Badge>
                                            </div>
                                        ) : (
                                            <span className="text-muted-foreground text-sm">N/A</span>
                                        )}
                                    </TableCell>
                                    <TableCell className="text-right">
                                        <Badge
                                            variant={record.changeAmount > 0 ? "default" : record.changeAmount < 0 ? "destructive" : "secondary"}
                                            className="text-sm px-2"
                                        >
                                            {record.changeAmount > 0 ? '+' : ''}{record.changeAmount}
                                        </Badge>
                                    </TableCell>
                                    <TableCell>
                                        {record.reason}
                                    </TableCell>
                                    <TableCell className="text-sm font-mono text-muted-foreground">
                                        {record.referenceId || '-'}
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Image from 'next/image';
import Link from 'next/link';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { useToast } from '@/components/ui/use-toast';
import { formatPrice } from '@/lib/utils';
import {
  Loader2, ArrowLeft, Package, MapPin, User,
  CreditCard, Hash, ChevronRight, Phone, Mail,
  Calendar, Clock, ExternalLink, CheckCircle2,
  Circle, AlertCircle,
} from 'lucide-react';

interface OrderItem {
  productId: string;
  productName: string;
  productImage: string;
  price: number;
  quantity: number;
  size?: string;
  color?: string;
}

interface Order {
  _id: string;
  orderId: string;
  status: string;
  totalAmount: number;
  paymentMethod: string;
  createdAt: string;
  updatedAt: string;
  userId?: string;
  items: OrderItem[];
  address: {
    fullName: string;
    email: string;
    phone: string;
    street: string;
    city: string;
    state: string;
    zipCode: string;
    country?: string;
  };
  cancellationReason?: string;
}

const STATUS_CFG: Record<string, { label: string; pill: string; dot: string; bg: string }> = {
  placed:           { label: 'Placed',           pill: 'bg-blue-100 text-blue-700 border-blue-200',       dot: 'bg-blue-500',    bg: 'from-blue-50' },
  packed:           { label: 'Packed',           pill: 'bg-violet-100 text-violet-700 border-violet-200', dot: 'bg-violet-500',  bg: 'from-violet-50' },
  shipped:          { label: 'Shipped',          pill: 'bg-amber-100 text-amber-700 border-amber-200',    dot: 'bg-amber-500',   bg: 'from-amber-50' },
  out_for_delivery: { label: 'Out for Delivery', pill: 'bg-orange-100 text-orange-700 border-orange-200', dot: 'bg-orange-500',  bg: 'from-orange-50' },
  delivered:        { label: 'Delivered',        pill: 'bg-emerald-100 text-emerald-700 border-emerald-200', dot: 'bg-emerald-500', bg: 'from-emerald-50' },
  cancelled:        { label: 'Cancelled',        pill: 'bg-red-100 text-red-700 border-red-200',          dot: 'bg-red-500',     bg: 'from-red-50' },
  returned:         { label: 'Returned',         pill: 'bg-gray-100 text-gray-600 border-gray-300',       dot: 'bg-gray-400',    bg: 'from-gray-50' },
};

const TIMELINE = [
  { key: 'placed',           label: 'Order Placed' },
  { key: 'packed',           label: 'Packed' },
  { key: 'shipped',          label: 'Shipped' },
  { key: 'out_for_delivery', label: 'Out for Delivery' },
  { key: 'delivered',        label: 'Delivered' },
];

function StatusBadge({ status }: { status: string }) {
  const c = STATUS_CFG[status] ?? STATUS_CFG.placed;
  return (
    <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-bold border ${c.pill}`}>
      <span className={`w-2 h-2 rounded-full ${c.dot}`} />
      {c.label}
    </span>
  );
}

function SectionCard({ icon: Icon, title, children }: { icon: any; title: string; children: React.ReactNode }) {
  return (
    <div className="bg-white dark:bg-card rounded-2xl border border-border shadow-sm overflow-hidden">
      <div className="flex items-center gap-2.5 px-5 py-3.5 border-b border-border bg-muted/40">
        <Icon className="h-4 w-4 text-muted-foreground" />
        <h3 className="text-sm font-semibold">{title}</h3>
      </div>
      <div className="p-5">{children}</div>
    </div>
  );
}

function Row({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex items-start justify-between gap-4 py-2.5 border-b border-border/50 last:border-0">
      <span className="text-xs text-muted-foreground shrink-0 pt-0.5">{label}</span>
      <div className="text-sm font-medium text-right">{children}</div>
    </div>
  );
}

export default function AdminOrderDetailPage() {
  const params = useParams();
  const router = useRouter();
  const { toast } = useToast();
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const id = typeof params.id === 'string' ? params.id : params.id?.[0];

  useEffect(() => {
    if (!id) return;
    fetch(`/api/orders/${id}`)
      .then(r => r.json())
      .then(d => setOrder(d))
      .catch(() => toast({ title: 'Failed to load order', variant: 'destructive' }))
      .finally(() => setLoading(false));
  }, [id]);

  const handleStatusChange = async (status: string) => {
    if (!order) return;
    setSaving(true);
    try {
      const res = await fetch(`/api/orders/${order._id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status }),
      });
      if (res.ok) {
        setOrder(await res.json());
        toast({ title: '✅ Status updated', description: `Now: ${STATUS_CFG[status]?.label ?? status}` });
      } else {
        const e = await res.json();
        toast({ title: 'Update failed', description: e.error, variant: 'destructive' });
      }
    } catch { toast({ title: 'Network error', variant: 'destructive' }); }
    finally { setSaving(false); }
  };

  /* ── Loading / not found ── */
  if (loading) return (
    <div className="flex items-center justify-center min-h-[60vh]">
      <Loader2 className="h-10 w-10 animate-spin text-primary" />
    </div>
  );

  if (!order || (order as any).error) return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
      <AlertCircle className="h-14 w-14 text-muted-foreground/40" />
      <p className="text-muted-foreground font-medium">Order not found.</p>
      <Button variant="outline" onClick={() => router.push('/admin/orders')}>
        <ArrowLeft className="h-4 w-4 mr-2" /> Back to Orders
      </Button>
    </div>
  );

  const created = new Date(order.createdAt);
  const updated = new Date(order.updatedAt);
  const cfg = STATUS_CFG[order.status] ?? STATUS_CFG.placed;
  const timelineIdx = TIMELINE.findIndex(t => t.key === order.status);
  const isTerminal = order.status === 'cancelled' || order.status === 'returned';
  const totalQty = order.items.reduce((s, i) => s + i.quantity, 0);

  return (
    <div className="max-w-5xl space-y-6">

      {/* ── Breadcrumb ── */}
      <div className="flex items-center gap-1.5 text-sm text-muted-foreground">
        <button onClick={() => router.push('/admin/orders')} className="hover:text-foreground flex items-center gap-1 transition-colors">
          <ArrowLeft className="h-3.5 w-3.5" /> Orders
        </button>
        <ChevronRight className="h-3.5 w-3.5" />
        <span className="text-foreground font-semibold">#{order.orderId}</span>
      </div>

      {/* ── Hero header ── */}
      <div className={`rounded-2xl border border-border bg-gradient-to-r ${cfg.bg} to-transparent p-6 shadow-sm`}>
        <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-5">
          <div>
            <div className="flex items-center gap-3 flex-wrap">
              <h1 className="text-2xl font-bold tracking-tight">Order #{order.orderId}</h1>
              <StatusBadge status={order.status} />
            </div>
            <div className="flex flex-wrap gap-x-5 gap-y-1 mt-2 text-sm text-muted-foreground">
              <span className="flex items-center gap-1.5">
                <Calendar className="h-3.5 w-3.5" />
                {created.toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' })}
              </span>
              <span className="flex items-center gap-1.5">
                <Clock className="h-3.5 w-3.5" />
                {created.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}
              </span>
              <span className="flex items-center gap-1.5">
                <Package className="h-3.5 w-3.5" />
                {totalQty} item{totalQty !== 1 ? 's' : ''}
              </span>
            </div>
          </div>

          {/* Status changer */}
          <div className="flex items-center gap-2 shrink-0">
            {saving && <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />}
            <Select value={order.status} onValueChange={handleStatusChange} disabled={saving}>
              <SelectTrigger className="w-52 bg-white dark:bg-card shadow-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {Object.entries(STATUS_CFG).map(([val, c]) => (
                  <SelectItem key={val} value={val}>
                    <span className="flex items-center gap-2">
                      <span className={`w-2 h-2 rounded-full ${c.dot}`} />
                      {c.label}
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      </div>

      {/* ── Timeline ── */}
      {!isTerminal && (
        <div className="bg-white dark:bg-card rounded-2xl border border-border p-5 shadow-sm">
          <p className="text-xs font-semibold uppercase tracking-widest text-muted-foreground mb-5">Fulfilment Progress</p>
          <div className="relative flex items-start gap-0">
            {TIMELINE.map((step, i) => {
              const done = i <= timelineIdx;
              const active = i === timelineIdx;
              const sc = STATUS_CFG[step.key];
              return (
                <div key={step.key} className="flex-1 flex flex-col items-center relative">
                  {/* Connector line */}
                  {i < TIMELINE.length - 1 && (
                    <div className={`absolute top-4 left-1/2 w-full h-0.5 transition-colors ${i < timelineIdx ? 'bg-primary' : 'bg-border'}`} />
                  )}
                  {/* Dot */}
                  <div className={`relative z-10 w-8 h-8 rounded-full border-2 flex items-center justify-center transition-all ${
                    done
                      ? `${sc.dot} border-transparent`
                      : 'bg-white dark:bg-card border-border'
                  } ${active ? 'ring-4 ring-primary/20' : ''}`}>
                    {done
                      ? <CheckCircle2 className="h-4 w-4 text-white" />
                      : <Circle className="h-3.5 w-3.5 text-border" />
                    }
                  </div>
                  {/* Label */}
                  <p className={`text-[11px] text-center mt-2 font-medium leading-tight max-w-[70px] ${
                    active ? 'text-foreground' : done ? 'text-muted-foreground' : 'text-muted-foreground/40'
                  }`}>
                    {step.label}
                  </p>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Cancellation reason */}
      {isTerminal && order.cancellationReason && (
        <div className="rounded-2xl border border-red-200 bg-red-50 p-4 flex items-start gap-3">
          <AlertCircle className="h-4 w-4 text-red-500 mt-0.5 shrink-0" />
          <div>
            <p className="text-sm font-semibold text-red-700">Reason for {order.status}</p>
            <p className="text-sm text-red-600 mt-0.5">{order.cancellationReason}</p>
          </div>
        </div>
      )}

      {/* ── Main content grid ── */}
      <div className="grid md:grid-cols-5 gap-5">

        {/* LEFT — Items (3/5) */}
        <div className="md:col-span-3 space-y-5">
          <SectionCard icon={Package} title={`Order Items (${order.items.length} product${order.items.length !== 1 ? 's' : ''})`}>
            <div className="space-y-5">
              {order.items.map((item, i) => (
                <div key={i} className={`flex gap-4 ${i > 0 ? 'pt-5 border-t border-border' : ''}`}>
                  {/* Image */}
                  <div className="relative w-20 h-24 rounded-xl overflow-hidden bg-muted shrink-0 border border-border">
                    {item.productImage ? (
                      <Image src={item.productImage} alt={item.productName} fill className="object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <Package className="h-6 w-6 text-muted-foreground/40" />
                      </div>
                    )}
                  </div>

                  {/* Info */}
                  <div className="flex-1 min-w-0">
                    <p className="font-semibold text-sm leading-snug">{item.productName}</p>
                    {/* Variant chips */}
                    <div className="flex flex-wrap gap-1.5 mt-2">
                      {item.size && (
                        <span className="inline-flex items-center px-2 py-0.5 rounded-full bg-muted text-xs font-medium">
                          Size: {item.size}
                        </span>
                      )}
                      {item.color && (
                        <span className="inline-flex items-center px-2 py-0.5 rounded-full bg-muted text-xs font-medium">
                          Colour: {item.color}
                        </span>
                      )}
                    </div>
                    <p className="text-sm text-muted-foreground mt-2">
                      {formatPrice(item.price)} × {item.quantity} = <span className="font-bold text-foreground">{formatPrice(item.price * item.quantity)}</span>
                    </p>
                    <Link
                      href={`/admin/products/edit/${item.productId}`}
                      className="inline-flex items-center gap-1 text-xs text-primary hover:underline mt-1.5"
                    >
                      <ExternalLink className="h-3 w-3" /> View product
                    </Link>
                  </div>

                  {/* Qty bubble */}
                  <div className="shrink-0">
                    <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center text-sm font-bold">
                      ×{item.quantity}
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* Order totals */}
            <div className="mt-6 pt-4 border-t border-border space-y-2">
              <div className="flex justify-between text-sm">
                <span className="text-muted-foreground">Subtotal</span>
                <span>{formatPrice(order.totalAmount)}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-muted-foreground">Shipping</span>
                <span className="text-emerald-600 font-semibold">Free</span>
              </div>
              <div className="flex justify-between items-center pt-3 border-t border-border">
                <span className="font-bold">Total</span>
                <span className="text-xl font-bold text-primary">{formatPrice(order.totalAmount)}</span>
              </div>
            </div>
          </SectionCard>
        </div>

        {/* RIGHT — Sidebar (2/5) */}
        <div className="md:col-span-2 space-y-4">

          {/* Customer */}
          <SectionCard icon={User} title="Customer">
            <div className="space-y-0">
              <p className="font-semibold text-sm mb-3">{order.address.fullName}</p>
              <Row label="Email">
                <a href={`mailto:${order.address.email}`} className="text-primary hover:underline flex items-center gap-1 justify-end">
                  <Mail className="h-3 w-3" />{order.address.email}
                </a>
              </Row>
              <Row label="Phone">
                <a href={`tel:${order.address.phone}`} className="text-primary hover:underline flex items-center gap-1 justify-end">
                  <Phone className="h-3 w-3" />{order.address.phone}
                </a>
              </Row>
              <Row label="Type">
                {order.userId ? (
                  <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-blue-100 text-blue-700 text-[11px] font-semibold">Registered</span>
                ) : (
                  <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-gray-100 text-gray-600 text-[11px] font-semibold">Guest</span>
                )}
              </Row>
            </div>
          </SectionCard>

          {/* Address */}
          <SectionCard icon={MapPin} title="Delivery Address">
            <address className="not-italic text-sm space-y-1 text-muted-foreground leading-relaxed">
              <p className="text-foreground font-semibold">{order.address.fullName}</p>
              <p>{order.address.street}</p>
              <p>{order.address.city}, {order.address.state} – {order.address.zipCode}</p>
              {order.address.country && <p>{order.address.country}</p>}
            </address>
          </SectionCard>

          {/* Payment */}
          <SectionCard icon={CreditCard} title="Payment">
            <Row label="Method">
              {order.paymentMethod === 'cod' ? (
                <span className="font-semibold">Cash on Delivery</span>
              ) : (
                <span className="font-semibold capitalize">{order.paymentMethod}</span>
              )}
            </Row>
            <Row label="Amount">
              <span className="font-bold text-base text-primary">{formatPrice(order.totalAmount)}</span>
            </Row>
            <Row label="Payment status">
              {order.paymentMethod === 'cod' ? (
                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-100 text-amber-700 text-[11px] font-semibold">Pending (COD)</span>
              ) : (
                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700 text-[11px] font-semibold">✓ Paid</span>
              )}
            </Row>
          </SectionCard>

          {/* Order meta */}
          <SectionCard icon={Hash} title="Order Info">
            <Row label="Order ID"><span className="font-mono font-bold">{order.orderId}</span></Row>
            <Row label="Placed">
              {created.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}
            </Row>
            <Row label="Last update">
              {updated.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}{' '}
              <span className="text-muted-foreground text-xs ml-1">
                {updated.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}
              </span>
            </Row>
            <Row label="Total items"><span className="font-semibold">{totalQty}</span></Row>
          </SectionCard>
        </div>
      </div>

      {/* Back */}
      <Button variant="outline" onClick={() => router.push('/admin/orders')} className="mt-2">
        <ArrowLeft className="h-4 w-4 mr-2" /> Back to All Orders
      </Button>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from '@/components/ui/use-toast';
import { Loader2, Upload, X, Plus } from 'lucide-react';

export default function EditProductPage() {
  const router = useRouter();
  const params = useParams();
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploadingImages, setUploadingImages] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    compareAtPrice: '',
    category: '',
    categoryId: '',
    sizes: [] as string[],
    colors: [] as string[],
    images: [] as string[],
    featured: false,
    variants: [] as { size: string; color: string; stock: string | number }[],
    colorImages: [] as { color: string; image: string }[],
  });

  const [sizes, setSizes] = useState<string[]>([]);
  const [colors, setColors] = useState<{ name: string; hex: string }[]>([]);
  const [categories, setCategories] = useState<{ _id: string; name: string; slug: string }[]>([]);
  const [homepageSections, setHomepageSections] = useState<{ _id: string; title: string; type: string; linkedProductIds: { _id: string }[] }[]>([]);
  const [showInSectionIds, setShowInSectionIds] = useState<string[]>([]);

  const sectionTypesWithProducts = ['trending', 'new_arrivals', 'promo', 'category'];

  useEffect(() => {
    fetchProduct();
  }, []);

  useEffect(() => {
    fetch('/api/categories')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => setCategories(Array.isArray(data) ? data : []))
      .catch(() => setCategories([]));
  }, []);

  // Sync categoryId from category name when editing old products that only have category string
  useEffect(() => {
    if (categories.length === 0 || !formData.category || formData.categoryId) return;
    const match = categories.find(
      (c) => c.name === formData.category || c.slug === formData.category
    );
    if (match) {
      setFormData((prev) => ({ ...prev, categoryId: match._id }));
    }
  }, [categories, formData.category, formData.categoryId]);

  useEffect(() => {
    fetch('/api/sizes')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => setSizes(data.map((s: { name: string }) => s.name)))
      .catch(() => setSizes([]));
  }, []);

  useEffect(() => {
    fetch('/api/colors')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => setColors(Array.isArray(data) ? data.map((c: { name: string; hex: string }) => ({ name: c.name, hex: c.hex })) : []))
      .catch(() => setColors([]));
  }, []);

  useEffect(() => {
    fetch('/api/homepage-sections')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => {
        const list = Array.isArray(data) ? data : [];
        const filtered = list.filter((s: { type: string }) => sectionTypesWithProducts.includes(s.type));
        setHomepageSections(filtered);
        const productId = typeof params.id === 'string' ? params.id : params.id?.[0];
        if (productId) {
          const included = filtered
            .filter((s: { linkedProductIds: { _id: string }[] }) =>
              (s.linkedProductIds || []).some((p: any) => (typeof p === 'object' ? p._id : p) === productId)
            )
            .map((s: { _id: string }) => s._id);
          setShowInSectionIds(included);
        }
      })
      .catch(() => setHomepageSections([]));
  }, [params.id]);

  const fetchProduct = async () => {
    try {
      const response = await fetch(`/api/products/${params.id}`);
      if (response.ok) {
        const data = await response.json();
        const catId = data.categoryId?.toString?.() || data.categoryId || '';
        const catName = data.category || '';
        setFormData({
          name: data.name,
          description: data.description,
          price: data.price.toString(),
          compareAtPrice: data.compareAtPrice?.toString() || '',
          category: catName,
          categoryId: catId,
          sizes: data.sizes,
          colors: data.colors,
          images: data.images,
          featured: data.featured,
          variants: data.variants || [],
          colorImages: (data.colorImages || []).map((ci: any) => ({ color: ci.color, image: ci.image })),
        });
      } else {
        toast({
          title: 'Product not found',
          variant: 'destructive',
        });
        router.push('/admin/products');
      }
    } catch (error) {
      console.error('Failed to fetch product:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploadingImages(true);

    try {
      const uploadPromises = Array.from(files).map(async (file) => {
        const formData = new FormData();
        formData.append('file', file);

        const response = await fetch('/api/upload', {
          method: 'POST',
          body: formData,
        });

        if (response.ok) {
          const data = await response.json();
          return data.url;
        }
        throw new Error('Upload failed');
      });

      const urls = await Promise.all(uploadPromises);
      setFormData((prev) => ({
        ...prev,
        images: [...prev.images, ...urls],
      }));

      toast({
        title: 'Images uploaded',
        description: `${urls.length} image(s) uploaded successfully`,
      });
    } catch (error) {
      toast({
        title: 'Upload failed',
        description: 'Failed to upload images',
        variant: 'destructive',
      });
    } finally {
      setUploadingImages(false);
    }
  };

  const handleRemoveImage = (index: number) => {
    const removedUrl = formData.images[index];
    setFormData((prev) => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index),
      // Also clear any color mapping that used this image
      colorImages: prev.colorImages.filter((ci) => ci.image !== removedUrl),
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);

    if (formData.images.length === 0) {
      toast({
        title: 'No images',
        description: 'Please upload at least one image',
        variant: 'destructive',
      });
      setSaving(false);
      return;
    }

    if (formData.sizes.length === 0) {
      toast({
        title: 'No sizes',
        description: 'Please select at least one size',
        variant: 'destructive',
      });
      setSaving(false);
      return;
    }

    try {
      const response = await fetch(`/api/products/${params.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          price: parseFloat(formData.price),
          compareAtPrice: formData.compareAtPrice ? parseFloat(formData.compareAtPrice) : undefined,
          stock: formData.variants.reduce((sum, v) => sum + (parseInt(String(v.stock)) || 0), 0),
          variants: formData.variants.map(v => ({ ...v, stock: parseInt(String(v.stock)) || 0 })),
          colorImages: formData.colorImages,
        }),
      });

      if (response.ok) {
        const productId = typeof params.id === 'string' ? params.id : params.id?.[0];
        if (productId) {
          for (const section of homepageSections) {
            const currentIds = (section.linkedProductIds || []).map((p: any) => (typeof p === 'object' ? p._id : p));
            const shouldInclude = showInSectionIds.includes(section._id);
            const hasProduct = currentIds.includes(productId);
            let newIds: string[];
            if (shouldInclude && !hasProduct) newIds = [...currentIds, productId];
            else if (!shouldInclude && hasProduct) newIds = currentIds.filter((id) => id !== productId);
            else continue;
            await fetch(`/api/homepage-sections/${section._id}`, {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ linkedProductIds: newIds }),
            });
          }
        }
        toast({
          title: 'Product updated',
          description: 'Product has been updated successfully',
        });
        router.push('/admin/products');
      } else {
        const data = await response.json();
        toast({
          title: 'Failed to update product',
          description: data.error,
          variant: 'destructive',
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update product',
        variant: 'destructive',
      });
    } finally {
      setSaving(false);
    }
  };

  const toggleShowInSection = (sectionId: string) => {
    setShowInSectionIds((prev) =>
      prev.includes(sectionId) ? prev.filter((id) => id !== sectionId) : [...prev, sectionId]
    );
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="max-w-3xl pb-20">
      <h2 className="text-3xl font-bold mb-6">Edit Product</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <Card>
          <CardHeader>
            <CardTitle>Basic Information</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name">Product Name *</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description *</Label>
              <textarea
                id="description"
                className="w-full min-h-[100px] rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="price">Price (₹) *</Label>
                <Input
                  id="price"
                  type="number"
                  step="0.01"
                  value={formData.price}
                  onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="compareAtPrice">Compare at Price (₹)</Label>
                <Input
                  id="compareAtPrice"
                  type="number"
                  step="0.01"
                  value={formData.compareAtPrice}
                  onChange={(e) => setFormData({ ...formData, compareAtPrice: e.target.value })}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="category">Category *</Label>
              <Select
                value={formData.categoryId}
                onValueChange={(value) => {
                  const cat = categories.find((c) => c._id === value);
                  setFormData({ ...formData, categoryId: value, category: cat?.name ?? '' });
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select category" />
                </SelectTrigger>
                <SelectContent>
                  {categories.map((c) => (
                    <SelectItem key={c._id} value={c._id}>
                      {c.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {categories.length === 0 && (
                <p className="text-xs text-muted-foreground">No categories yet. Add them in Admin → Categories.</p>
              )}
            </div>

            <div className="flex items-center space-x-2">
              <Checkbox
                id="featured"
                checked={formData.featured}
                onCheckedChange={(checked) =>
                  setFormData({ ...formData, featured: checked as boolean })
                }
              />
              <Label htmlFor="featured" className="cursor-pointer">
                Featured Product
              </Label>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Sizes *</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-3 gap-2">
              {sizes.map((size) => (
                <Button
                  key={size}
                  type="button"
                  variant={formData.sizes.includes(size) ? 'default' : 'outline'}
                  onClick={() => {
                    setFormData((prev) => ({
                      ...prev,
                      sizes: prev.sizes.includes(size)
                        ? prev.sizes.filter((s) => s !== size)
                        : [...prev.sizes, size],
                    }));
                  }}
                >
                  {size}
                </Button>
              ))}
            </div>
          </CardContent>
        </Card>

        {homepageSections.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Show on homepage</CardTitle>
              <p className="text-sm text-muted-foreground font-normal">Tick sections where this product should appear.</p>
            </CardHeader>
            <CardContent>
              <div className="flex flex-wrap gap-4">
                {homepageSections.map((section) => (
                  <div key={section._id} className="flex items-center space-x-2">
                    <Checkbox
                      id={`section-${section._id}`}
                      checked={showInSectionIds.includes(section._id)}
                      onCheckedChange={() => toggleShowInSection(section._id)}
                    />
                    <Label htmlFor={`section-${section._id}`} className="cursor-pointer text-sm font-normal">
                      {section.title || section.type}
                    </Label>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        <Card>
          <CardHeader>
            <CardTitle>Colors *</CardTitle>
          </CardHeader>
          <CardContent>
            {colors.length === 0 ? (
              <p className="text-sm text-muted-foreground">Loading colours…</p>
            ) : (
              <div className="grid grid-cols-2 gap-2">
                {colors.map((color) => (
                  <div key={color.name} className="flex items-center space-x-2">
                    <Checkbox
                      id={`color-${color.name}`}
                      checked={formData.colors.includes(color.name)}
                      onCheckedChange={(checked) => {
                        setFormData((prev) => ({
                          ...prev,
                          colors: checked
                            ? [...prev.colors, color.name]
                            : prev.colors.filter((c) => c !== color.name),
                        }));
                      }}
                    />
                    <div
                      className="h-4 w-4 rounded-full border border-border shadow-sm shrink-0"
                      style={{ backgroundColor: color.hex }}
                    />
                    <Label htmlFor={`color-${color.name}`} className="cursor-pointer">
                      {color.name}
                    </Label>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Variants & Stock</CardTitle>
            <p className="text-sm text-muted-foreground">Manage stock for specific sizes and colors.</p>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Total Stock — auto-calculated from variants */}
            <div className="flex items-center gap-4 p-4 rounded-xl bg-muted/50 border border-border">
              <div className="flex-1 space-y-1">
                <Label className="text-sm font-semibold">Total Stock</Label>
                <p className="text-xs text-muted-foreground">Auto-calculated from the sum of all variant stocks below.</p>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-32 h-10 rounded-md border border-border bg-background px-3 flex items-center justify-center font-bold text-lg select-none">
                  {formData.variants.reduce((sum, v) => sum + (parseInt(String(v.stock)) || 0), 0)}
                </div>
              </div>
            </div>
            <div className="border-b border-border" />
            {formData.variants.length > 0 ? (
              <div className="space-y-3">
                <div className="grid grid-cols-4 gap-4 font-medium text-sm text-muted-foreground pb-2 border-b">
                  <div>Size</div>
                  <div>Color</div>
                  <div>Stock</div>
                  <div></div>
                </div>
                {formData.variants.map((v, idx) => (
                  <div key={idx} className="grid grid-cols-4 gap-4 items-center">
                    <Select
                      value={v.size || undefined}
                      onValueChange={(val) => {
                        const newVariants = [...formData.variants];
                        newVariants[idx].size = val;
                        setFormData({ ...formData, variants: newVariants });
                      }}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select size" />
                      </SelectTrigger>
                      <SelectContent>
                        {formData.sizes.map((s) => (
                          <SelectItem key={s} value={s}>{s}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <Select
                      value={v.color || undefined}
                      onValueChange={(val) => {
                        const newVariants = [...formData.variants];
                        newVariants[idx].color = val;
                        setFormData({ ...formData, variants: newVariants });
                      }}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select color" />
                      </SelectTrigger>
                      <SelectContent>
                        {formData.colors.map((c) => (
                          <SelectItem key={c} value={c}>{c}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <Input
                      type="number"
                      min="0"
                      value={String(v.stock)}
                      onChange={(e) => {
                        const newVariants = [...formData.variants];
                        newVariants[idx] = { ...newVariants[idx], stock: e.target.value };
                        setFormData({ ...formData, variants: newVariants });
                      }}
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="text-destructive w-fit"
                      onClick={() => {
                        setFormData({
                          ...formData,
                          variants: formData.variants.filter((_, i) => i !== idx)
                        });
                      }}
                    >
                      <X className="h-4 w-4" />
                    </Button>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">No variants added yet.</p>
            )}

            <Button
              type="button"
              variant="outline"
              className="w-full mt-4"
              onClick={() => {
                setFormData({
                  ...formData,
                  variants: [...formData.variants, { size: formData.sizes[0] || '', color: formData.colors[0] || '', stock: '' }]
                });
              }}
            >
              <Plus className="h-4 w-4 mr-2" /> Add Variant
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Images *</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label htmlFor="images" className="cursor-pointer">
                <div className="border-2 border-dashed rounded-lg p-8 text-center hover:border-primary transition-colors">
                  {uploadingImages ? (
                    <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                  ) : (
                    <>
                      <Upload className="h-8 w-8 mx-auto mb-2" />
                      <p className="text-sm text-muted-foreground">
                        Click to upload more images
                      </p>
                    </>
                  )}
                </div>
                <Input
                  id="images"
                  type="file"
                  multiple
                  accept="image/*"
                  className="hidden"
                  onChange={handleImageUpload}
                  disabled={uploadingImages}
                />
              </Label>
            </div>

            {formData.images.length > 0 && (
              <div className="grid grid-cols-4 gap-4">
                {formData.images.map((url, index) => (
                  <div key={index} className="relative aspect-square rounded-lg overflow-hidden border">
                    <img src={url} alt={`Product ${index + 1}`} className="object-cover w-full h-full" />
                    <button
                      type="button"
                      onClick={() => handleRemoveImage(index)}
                      className="absolute top-2 right-2 bg-destructive text-white rounded-full p-1"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Color → Image Mapping */}
        {formData.colors.length > 0 && formData.images.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Color → Image Mapping</CardTitle>
              <p className="text-sm text-muted-foreground">Assign a specific image to each color. When a customer selects a color, that image will be shown automatically.</p>
            </CardHeader>
            <CardContent className="space-y-3">
              {formData.colors.map((color) => {
                const mapped = formData.colorImages.find((ci) => ci.color === color);
                return (
                  <div key={color} className="flex items-center gap-4">
                    <span className="w-20 text-sm font-medium shrink-0">{color}</span>
                    <Select
                      value={mapped?.image || '__none__'}
                      onValueChange={(val) => {
                        setFormData((prev) => {
                          const rest = prev.colorImages.filter((ci) => ci.color !== color);
                          if (val === '__none__') return { ...prev, colorImages: rest };
                          return { ...prev, colorImages: [...rest, { color, image: val }] };
                        });
                      }}
                    >
                      <SelectTrigger className="flex-1">
                        <SelectValue placeholder="No image assigned" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="__none__">— No image assigned —</SelectItem>
                        {formData.images.map((url, idx) => (
                          <SelectItem key={url} value={url}>
                            Image {idx + 1}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    {mapped?.image && (
                      <img src={mapped.image} alt={color} className="w-12 h-12 rounded-lg object-cover border shrink-0" />
                    )}
                  </div>
                );
              })}
            </CardContent>
          </Card>
        )}

        <div className="flex gap-4">
          <Button type="submit" disabled={saving} className="flex-1">
            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Save Changes
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Cancel
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from '@/components/ui/use-toast';
import { Loader2, Upload, X, Plus } from 'lucide-react';

export default function NewProductPage() {
  const router = useRouter();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [uploadingImages, setUploadingImages] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    compareAtPrice: '',
    category: '',
    categoryId: '',
    sizes: [] as string[],
    colors: [] as string[],
    images: [] as string[],
    featured: false,
    variants: [] as { size: string; color: string; stock: string | number }[],
    colorImages: [] as { color: string; image: string }[],
  });

  const [sizes, setSizes] = useState<string[]>([]);
  const [colors, setColors] = useState<{ name: string; hex: string }[]>([]);
  const [categories, setCategories] = useState<{ _id: string; name: string; slug: string }[]>([]);
  const [homepageSections, setHomepageSections] = useState<{ _id: string; title: string; type: string; linkedProductIds: { _id: string }[] }[]>([]);
  const [showInSectionIds, setShowInSectionIds] = useState<string[]>([]);

  const sectionTypesWithProducts = ['trending', 'new_arrivals', 'promo', 'category'];

  useEffect(() => {
    fetch('/api/sizes')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => setSizes(data.map((s: { name: string }) => s.name)))
      .catch(() => setSizes([]));
  }, []);

  useEffect(() => {
    fetch('/api/colors')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => setColors(Array.isArray(data) ? data.map((c: { name: string; hex: string }) => ({ name: c.name, hex: c.hex })) : []))
      .catch(() => setColors([]));
  }, []);

  useEffect(() => {
    fetch('/api/categories')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => {
        const list = Array.isArray(data) ? data : [];
        setCategories(list);
        if (list.length > 0) {
          setFormData((prev) =>
            prev.categoryId ? prev : { ...prev, category: list[0].name, categoryId: list[0]._id }
          );
        }
      })
      .catch(() => setCategories([]));
  }, []);

  useEffect(() => {
    fetch('/api/homepage-sections')
      .then((res) => res.ok ? res.json() : [])
      .then((data) => {
        const list = Array.isArray(data) ? data : [];
        setHomepageSections(list.filter((s: { type: string }) => sectionTypesWithProducts.includes(s.type)));
      })
      .catch(() => setHomepageSections([]));
  }, []);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploadingImages(true);

    try {
      const uploadPromises = Array.from(files).map(async (file) => {
        const formData = new FormData();
        formData.append('file', file);

        const response = await fetch('/api/upload', {
          method: 'POST',
          body: formData,
        });

        if (response.ok) {
          const data = await response.json();
          return data.url;
        }
        throw new Error('Upload failed');
      });

      const urls = await Promise.all(uploadPromises);
      setFormData((prev) => ({
        ...prev,
        images: [...prev.images, ...urls],
      }));

      toast({
        title: 'Images uploaded',
        description: `${urls.length} image(s) uploaded successfully`,
      });
    } catch (error) {
      toast({
        title: 'Upload failed',
        description: 'Failed to upload images',
        variant: 'destructive',
      });
    } finally {
      setUploadingImages(false);
    }
  };

  const handleRemoveImage = (index: number) => {
    const removedUrl = formData.images[index];
    setFormData((prev) => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index),
      colorImages: prev.colorImages.filter((ci) => ci.image !== removedUrl),
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    if (formData.images.length === 0) {
      toast({
        title: 'No images',
        description: 'Please upload at least one image',
        variant: 'destructive',
      });
      setLoading(false);
      return;
    }

    if (formData.sizes.length === 0) {
      toast({
        title: 'No sizes',
        description: 'Please select at least one size',
        variant: 'destructive',
      });
      setLoading(false);
      return;
    }

    try {
      const response = await fetch('/api/products', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          category: formData.category,
          categoryId: formData.categoryId || undefined,
          price: parseFloat(formData.price),
          compareAtPrice: formData.compareAtPrice ? parseFloat(formData.compareAtPrice) : undefined,
          stock: formData.variants.reduce((sum, v) => sum + (parseInt(String(v.stock)) || 0), 0),
          variants: formData.variants.map(v => ({ ...v, stock: parseInt(String(v.stock)) || 0 })),
          colorImages: formData.colorImages,
        }),
      });

      if (response.ok) {
        const created = await response.json();
        const newProductId = created._id;
        for (const sectionId of showInSectionIds) {
          const section = homepageSections.find((s) => s._id === sectionId);
          if (section) {
            const currentIds = (section.linkedProductIds || []).map((p: any) => (typeof p === 'object' ? p._id : p));
            if (!currentIds.includes(newProductId)) {
              await fetch(`/api/homepage-sections/${sectionId}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ linkedProductIds: [...currentIds, newProductId] }),
              });
            }
          }
        }
        toast({
          title: 'Product created',
          description: 'Product has been created successfully',
        });
        router.push('/admin/products');
      } else {
        const data = await response.json();
        toast({
          title: 'Failed to create product',
          description: data.error,
          variant: 'destructive',
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to create product',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const toggleShowInSection = (sectionId: string) => {
    setShowInSectionIds((prev) =>
      prev.includes(sectionId) ? prev.filter((id) => id !== sectionId) : [...prev, sectionId]
    );
  };

  return (
    <div className="max-w-3xl pb-20">
      <h2 className="text-3xl font-bold mb-6">Add New Product</h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <Card>
          <CardHeader>
            <CardTitle>Basic Information</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name">Product Name *</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description *</Label>
              <textarea
                id="description"
                className="w-full min-h-[100px] rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="price">Price (₹) *</Label>
                <Input
                  id="price"
                  type="number"
                  step="0.01"
                  value={formData.price}
                  onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="compareAtPrice">Compare at Price (₹)</Label>
                <Input
                  id="compareAtPrice"
                  type="number"
                  step="0.01"
                  value={formData.compareAtPrice}
                  onChange={(e) => setFormData({ ...formData, compareAtPrice: e.target.value })}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="category">Category *</Label>
              <Select
                value={formData.categoryId}
                onValueChange={(value) => {
                  const cat = categories.find((c) => c._id === value);
                  setFormData({ ...formData, categoryId: value, category: cat?.name ?? '' });
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select category" />
                </SelectTrigger>
                <SelectContent>
                  {categories.map((c) => (
                    <SelectItem key={c._id} value={c._id}>
                      {c.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {categories.length === 0 && (
                <p className="text-xs text-muted-foreground">No categories yet. Add them in Admin → Categories.</p>
              )}
            </div>

            <div className="flex items-center space-x-2">
              <Checkbox
                id="featured"
                checked={formData.featured}
                onCheckedChange={(checked) =>
                  setFormData({ ...formData, featured: checked as boolean })
                }
              />
              <Label htmlFor="featured" className="cursor-pointer">
                Featured Product
              </Label>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Sizes *</CardTitle>
          </CardHeader>
          <CardContent>
            {sizes.length === 0 ? (
              <p className="text-sm text-muted-foreground">Loading sizes…</p>
            ) : (
              <div className="grid grid-cols-3 gap-2">
                {sizes.map((size) => (
                  <Button
                    key={size}
                    type="button"
                    variant={formData.sizes.includes(size) ? 'default' : 'outline'}
                    onClick={() => {
                      setFormData((prev) => ({
                        ...prev,
                        sizes: prev.sizes.includes(size)
                          ? prev.sizes.filter((s) => s !== size)
                          : [...prev.sizes, size],
                      }));
                    }}
                  >
                    {size}
                  </Button>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {homepageSections.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Show on homepage</CardTitle>
              <p className="text-sm text-muted-foreground font-normal">Tick sections where this product should appear.</p>
            </CardHeader>
            <CardContent>
              <div className="flex flex-wrap gap-4">
                {homepageSections.map((section) => (
                  <div key={section._id} className="flex items-center space-x-2">
                    <Checkbox
                      id={`section-${section._id}`}
                      checked={showInSectionIds.includes(section._id)}
                      onCheckedChange={() => toggleShowInSection(section._id)}
                    />
                    <Label htmlFor={`section-${section._id}`} className="cursor-pointer text-sm font-normal">
                      {section.title || section.type}
                    </Label>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        <Card>
          <CardHeader>
            <CardTitle>Colors *</CardTitle>
          </CardHeader>
          <CardContent>
            {colors.length === 0 ? (
              <p className="text-sm text-muted-foreground">Loading colours…</p>
            ) : (
              <div className="grid grid-cols-2 gap-2">
                {colors.map((color) => (
                  <div key={color.name} className="flex items-center space-x-2">
                    <Checkbox
                      id={`color-${color.name}`}
                      checked={formData.colors.includes(color.name)}
                      onCheckedChange={(checked) => {
                        setFormData((prev) => ({
                          ...prev,
                          colors: checked
                            ? [...prev.colors, color.name]
                            : prev.colors.filter((c) => c !== color.name),
                        }));
                      }}
                    />
                    <div
                      className="h-4 w-4 rounded-full border border-border shadow-sm shrink-0"
                      style={{ backgroundColor: color.hex }}
                    />
                    <Label htmlFor={`color-${color.name}`} className="cursor-pointer">
                      {color.name}
                    </Label>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Variants & Stock</CardTitle>
            <p className="text-sm text-muted-foreground">Manage stock for specific sizes and colors.</p>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Total Stock — auto-calculated, read-only */}
            <div className="flex items-center gap-4 p-4 rounded-xl bg-muted/50 border border-border">
              <div className="flex-1 space-y-1">
                <Label className="text-sm font-semibold">Total Stock</Label>
                <p className="text-xs text-muted-foreground">Auto-calculated from the sum of all variant stocks below.</p>
              </div>
              <div className="w-32 h-10 rounded-md border border-border bg-background px-3 flex items-center justify-center font-bold text-lg select-none">
                {formData.variants.reduce((sum, v) => sum + (parseInt(String(v.stock)) || 0), 0)}
              </div>
            </div>
            <div className="border-b border-border" />
            {formData.variants.length > 0 ? (
              <div className="space-y-3">
                <div className="grid grid-cols-4 gap-4 font-medium text-sm text-muted-foreground pb-2 border-b">
                  <div>Size</div>
                  <div>Color</div>
                  <div>Stock</div>
                  <div></div>
                </div>
                {formData.variants.map((v, idx) => (
                  <div key={idx} className="grid grid-cols-4 gap-4 items-center">
                    <Select
                      value={v.size || undefined}
                      onValueChange={(val) => {
                        const newVariants = [...formData.variants];
                        newVariants[idx].size = val;
                        setFormData({ ...formData, variants: newVariants });
                      }}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select size" />
                      </SelectTrigger>
                      <SelectContent>
                        {formData.sizes.map((s) => (
                          <SelectItem key={s} value={s}>{s}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <Select
                      value={v.color || undefined}
                      onValueChange={(val) => {
                        const newVariants = [...formData.variants];
                        newVariants[idx].color = val;
                        setFormData({ ...formData, variants: newVariants });
                      }}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select color" />
                      </SelectTrigger>
                      <SelectContent>
                        {formData.colors.map((c) => (
                          <SelectItem key={c} value={c}>{c}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <Input
                      type="number"
                      min="0"
                      value={String(v.stock)}
                      onChange={(e) => {
                        const newVariants = [...formData.variants];
                        newVariants[idx] = { ...newVariants[idx], stock: e.target.value };
                        setFormData({ ...formData, variants: newVariants });
                      }}
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="text-destructive w-fit"
                      onClick={() => {
                        setFormData({
                          ...formData,
                          variants: formData.variants.filter((_, i) => i !== idx)
                        });
                      }}
                    >
                      <X className="h-4 w-4" />
                    </Button>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">No variants added yet.</p>
            )}

            <Button
              type="button"
              variant="outline"
              className="w-full mt-4"
              onClick={() => {
                setFormData({
                  ...formData,
                  variants: [...formData.variants, { size: formData.sizes[0] || '', color: formData.colors[0] || '', stock: '' }]
                });
              }}
            >
              <Plus className="h-4 w-4 mr-2" /> Add Variant
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Images *</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label htmlFor="images" className="cursor-pointer">
                <div className="border-2 border-dashed rounded-lg p-8 text-center hover:border-primary transition-colors">
                  {uploadingImages ? (
                    <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                  ) : (
                    <>
                      <Upload className="h-8 w-8 mx-auto mb-2" />
                      <p className="text-sm text-muted-foreground">
                        Click to upload images
                      </p>
                    </>
                  )}
                </div>
                <Input
                  id="images"
                  type="file"
                  multiple
                  accept="image/*"
                  className="hidden"
                  onChange={handleImageUpload}
                  disabled={uploadingImages}
                />
              </Label>
            </div>

            {formData.images.length > 0 && (
              <div className="grid grid-cols-4 gap-4">
                {formData.images.map((url, index) => (
                  <div key={index} className="relative aspect-square rounded-lg overflow-hidden border">
                    <img src={url} alt={`Product ${index + 1}`} className="object-cover w-full h-full" />
                    <button
                      type="button"
                      onClick={() => handleRemoveImage(index)}
                      className="absolute top-2 right-2 bg-destructive text-white rounded-full p-1"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Color → Image Mapping */}
        {formData.colors.length > 0 && formData.images.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Color → Image Mapping</CardTitle>
              <p className="text-sm text-muted-foreground">Assign a specific image to each color. When a customer selects a color, that image will be shown automatically.</p>
            </CardHeader>
            <CardContent className="space-y-3">
              {formData.colors.map((color) => {
                const mapped = formData.colorImages.find((ci) => ci.color === color);
                return (
                  <div key={color} className="flex items-center gap-4">
                    <span className="w-20 text-sm font-medium shrink-0">{color}</span>
                    <Select
                      value={mapped?.image || '__none__'}
                      onValueChange={(val) => {
                        setFormData((prev) => {
                          const rest = prev.colorImages.filter((ci) => ci.color !== color);
                          if (val === '__none__') return { ...prev, colorImages: rest };
                          return { ...prev, colorImages: [...rest, { color, image: val }] };
                        });
                      }}
                    >
                      <SelectTrigger className="flex-1">
                        <SelectValue placeholder="No image assigned" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="__none__">— No image assigned —</SelectItem>
                        {formData.images.map((url, idx) => (
                          <SelectItem key={url} value={url}>
                            Image {idx + 1}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    {mapped?.image && (
                      <img src={mapped.image} alt={color} className="w-12 h-12 rounded-lg object-cover border shrink-0" />
                    )}
                  </div>
                );
              })}
            </CardContent>
          </Card>
        )}

        <div className="flex gap-4">
          <Button type="submit" disabled={loading} className="flex-1">
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Create Product
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Cancel
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Trash2, Star, Loader2, Search, ExternalLink, Eye, EyeOff, Plus, Quote } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { useToast } from '@/components/ui/use-toast';
import Image from 'next/image';
import Link from 'next/link';

interface AdminReview {
  _id: string;
  productId: string;
  userId: string;
  userName: string;
  rating: number;
  title: string;
  body: string;
  createdAt: string;
  productName: string;
  productImage: string;
  productSlug: string;
  isHidden: boolean;
}

interface Testimonial {
  name: string;
  text: string;
  stars: number;
}

const DEFAULT_TESTIMONIALS: Testimonial[] = [
  { name: 'Priya M.', text: 'Absolutely love the quality! Fits perfectly and looks stunning.', stars: 5 },
  { name: 'Divya R.', text: 'Fast delivery and the packaging was beautiful. Will order again!', stars: 5 },
  { name: 'Ananya K.', text: 'The dress looked even better in person. Highly recommend AVANYAA!', stars: 5 },
  { name: 'Meera S.', text: 'Great customer service and the return process was so easy.', stars: 5 },
];

/* ── Star Picker ── */
function StarPicker({ value, onChange }: { value: number; onChange: (v: number) => void }) {
  return (
    <div className="flex gap-1">
      {[1, 2, 3, 4, 5].map(n => (
        <button key={n} type="button" onClick={() => onChange(n)}>
          <Star className={`h-5 w-5 transition-colors ${n <= value ? 'fill-amber-400 text-amber-400' : 'text-muted-foreground/30'}`} />
        </button>
      ))}
    </div>
  );
}

export default function AdminReviewsPage() {
  const { toast } = useToast();

  /* ── Product Reviews state ── */
  const [reviews, setReviews] = useState<AdminReview[]>([]);
  const [loadingReviews, setLoadingReviews] = useState(true);
  const [search, setSearch] = useState('');

  /* ── Testimonials state ── */
  const [testimonials, setTestimonials] = useState<Testimonial[]>(DEFAULT_TESTIMONIALS);
  const [loadingT, setLoadingT] = useState(true);
  const [savingT, setSavingT] = useState(false);

  /* ── Tab state ── */
  const [tab, setTab] = useState<'product' | 'testimonials'>('testimonials');

  /* ── Fetch product reviews ── */
  const fetchReviews = async () => {
    setLoadingReviews(true);
    try {
      const res = await fetch('/api/admin/reviews');
      const data = await res.json();
      if (res.ok) setReviews(data.reviews || []);
      else throw new Error(data.error || 'Failed to fetch');
    } catch (err: any) {
      toast({ title: 'Error', description: err.message, variant: 'destructive' });
    } finally {
      setLoadingReviews(false);
    }
  };

  /* ── Fetch testimonials ── */
  useEffect(() => {
    fetch('/api/settings')
      .then(r => r.json())
      .then(data => { if (data.testimonials?.length) setTestimonials(data.testimonials); })
      .catch(() => {})
      .finally(() => setLoadingT(false));
    fetchReviews();
  }, []);

  /* ── Product review actions ── */
  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this review? This action cannot be undone.')) return;
    try {
      const res = await fetch(`/api/reviews?id=${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('Failed to delete review');
      toast({ title: 'Review deleted successfully' });
      setReviews(reviews.filter(r => r._id !== id));
